-- HEALTH-002: CSM sentiment is a person's dated judgment, kept as history.
-- The newest rating per account feeds health until its expiry date.
CREATE TABLE buoy_sentiments (
 id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES buoy_accounts(id) ON DELETE CASCADE,
 rating TEXT NOT NULL CHECK(rating IN ('red','amber','green')), reason TEXT NOT NULL,
 recorded_by TEXT NOT NULL, recorded_at TEXT NOT NULL, expires_on TEXT NOT NULL
);
CREATE INDEX buoy_sentiments_account ON buoy_sentiments(account_id, recorded_at);

-- DATA-001: owner/admin settings such as per-source staleness thresholds.
CREATE TABLE buoy_settings (
 key TEXT PRIMARY KEY, value TEXT NOT NULL CHECK(json_valid(value)),
 updated_by TEXT NOT NULL, updated_at TEXT NOT NULL
);

-- BOUNDARY-004 (AUDIT-001 builds on it): durable audit rows keep an opaque subject
-- reference and no account foreign key, so they outlive the subject's erasure.
CREATE TABLE buoy_audit (
 id TEXT PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, subject TEXT NOT NULL,
 detail TEXT NOT NULL, occurred_at TEXT NOT NULL
);
CREATE INDEX buoy_audit_time ON buoy_audit(occurred_at);

-- AUDIT-001: migrate every retained event before dropping the cascading log.
-- The subject mapping lives only as long as the account. Audit rows have no FK.
CREATE TABLE buoy_audit_subjects (
 account_id TEXT PRIMARY KEY REFERENCES buoy_accounts(id) ON DELETE CASCADE,
 subject TEXT NOT NULL UNIQUE
);
INSERT INTO buoy_audit_subjects(account_id,subject)
 SELECT id,lower(hex(randomblob(16))) FROM buoy_accounts;
INSERT INTO buoy_audit(id,actor,action,subject,detail,occurred_at)
 SELECT e.id,e.actor,e.action,s.subject,'',e.occurred_at
 FROM buoy_events e JOIN buoy_audit_subjects s ON s.account_id=e.account_id;
-- Existing actors were kind:id:display-name; keep just kind:id.
UPDATE buoy_audit SET actor=substr(actor,1,instr(actor,':')+instr(substr(actor,instr(actor,':')+1),':')-1)
 WHERE instr(substr(actor,instr(actor,':')+1),':')>0;
DROP TABLE buoy_events;

-- PLAY-002: tasks carry an owner, priority, type and completion outcome.
-- Existing tasks are owned by the person who approved them.
ALTER TABLE buoy_tasks ADD COLUMN owner_id TEXT;
ALTER TABLE buoy_tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'medium' CHECK(priority IN ('low','medium','high','urgent'));
ALTER TABLE buoy_tasks ADD COLUMN type TEXT NOT NULL DEFAULT 'risk' CHECK(type IN ('risk','onboarding','adoption','renewal','expansion','general'));
ALTER TABLE buoy_tasks ADD COLUMN outcome TEXT;
UPDATE buoy_tasks SET owner_id=(SELECT substr(substr(p.approved_by,8),1,instr(substr(p.approved_by,8),':')-1) FROM buoy_proposals p WHERE p.id=buoy_tasks.proposal_id AND p.approved_by LIKE 'person:%');
CREATE INDEX buoy_tasks_owner ON buoy_tasks(owner_id) WHERE completed_at IS NULL;
-- An account's CSM. Reassignment moves the open tasks the previous CSM owned.
CREATE TABLE buoy_account_owners (
 account_id TEXT PRIMARY KEY REFERENCES buoy_accounts(id) ON DELETE CASCADE,
 owner_id TEXT NOT NULL, assigned_at TEXT NOT NULL
);
-- Each person's manager, who receives escalations of their overdue tasks.
CREATE TABLE buoy_people (
 person_id TEXT PRIMARY KEY, manager_id TEXT, CHECK(manager_id IS NULL OR manager_id<>person_id)
);
-- Away periods: inclusive UTC calendar dates, one named cover, no overlap per person.
CREATE TABLE buoy_away (
 id TEXT PRIMARY KEY, person_id TEXT NOT NULL, cover_id TEXT NOT NULL,
 starts_on TEXT NOT NULL, ends_on TEXT NOT NULL, recorded_at TEXT NOT NULL,
 CHECK(starts_on<=ends_on), CHECK(cover_id<>person_id)
);
CREATE INDEX buoy_away_person ON buoy_away(person_id, starts_on);
-- In-app reminders and escalations: one per task and kind. email records what the
-- mail provider said, never a delivery it did not report.
CREATE TABLE buoy_notifications (
 id TEXT PRIMARY KEY, person_id TEXT NOT NULL,
 task_id TEXT NOT NULL REFERENCES buoy_tasks(id) ON DELETE CASCADE,
 kind TEXT NOT NULL CHECK(kind IN ('due-soon','due-today','escalated')),
 on_date TEXT NOT NULL, created_at TEXT NOT NULL,
 email TEXT NOT NULL CHECK(email IN ('pending','accepted','failed','uncertain','development','no-provider','no-recipient')),
 UNIQUE(task_id, kind)
);
CREATE INDEX buoy_notifications_person ON buoy_notifications(person_id, created_at);

-- NOTIFY-001: one durable inbox event per source and recipient; mail is separate.
CREATE TABLE buoy_inbox (
 id TEXT PRIMARY KEY, person_id TEXT NOT NULL,
 account_id TEXT NOT NULL REFERENCES buoy_accounts(id) ON DELETE CASCADE,
 type TEXT NOT NULL CHECK(type IN ('mention','assignment','signal','approval')),
 source TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL,
 created_at TEXT NOT NULL, read_at TEXT, email TEXT NOT NULL DEFAULT 'pending', digest_id TEXT,
 UNIQUE(person_id,source)
);
CREATE INDEX buoy_inbox_person ON buoy_inbox(person_id,created_at);
CREATE TABLE buoy_notification_preferences (
 person_id TEXT PRIMARY KEY, frequency TEXT NOT NULL CHECK(frequency IN ('off','daily','weekly')),
 modes TEXT NOT NULL CHECK(json_valid(modes)), book_cursor INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE buoy_digests (
 id TEXT PRIMARY KEY, person_id TEXT NOT NULL, period TEXT NOT NULL,
 frequency TEXT NOT NULL, created_at TEXT NOT NULL, email TEXT NOT NULL,
 UNIQUE(person_id,frequency,period)
);
CREATE TABLE buoy_alert_state (
 account_id TEXT PRIMARY KEY REFERENCES buoy_accounts(id) ON DELETE CASCADE,
 fingerprint TEXT NOT NULL
);
CREATE TRIGGER buoy_task_assignment_notice AFTER INSERT ON buoy_tasks WHEN NEW.owner_id IS NOT NULL BEGIN
 INSERT OR IGNORE INTO buoy_inbox(id,person_id,account_id,type,source,title,body,created_at)
 VALUES(lower(hex(randomblob(16))),NEW.owner_id,NEW.account_id,'assignment','task:'||NEW.id||':'||NEW.owner_id,NEW.title,'A task was assigned to you.',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
END;
CREATE TRIGGER buoy_task_reassignment_notice AFTER UPDATE OF owner_id ON buoy_tasks WHEN NEW.owner_id IS NOT OLD.owner_id AND NEW.completed_at IS NULL BEGIN
 INSERT OR IGNORE INTO buoy_inbox(id,person_id,account_id,type,source,title,body,created_at)
 VALUES(lower(hex(randomblob(16))),NEW.owner_id,NEW.account_id,'assignment','reassignment:'||NEW.id||':'||lower(hex(randomblob(16))),NEW.title,'An open task was reassigned to you.',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
END;
CREATE TRIGGER buoy_approval_notice AFTER INSERT ON buoy_proposals BEGIN
 INSERT OR IGNORE INTO buoy_inbox(id,person_id,account_id,type,source,title,body,created_at)
 SELECT lower(hex(randomblob(16))),o.id,NEW.account_id,'approval','proposal:'||NEW.id,'Review '||NEW.kind||' proposal','A prepared proposal awaits owner or administrator approval.',NEW.prepared_at
 FROM oa_operators o WHERE o.status='active' AND o.role IN ('owner','admin');
END;

-- TEAM-001: owner-managed books, explicit reviewed assignment and handovers.
CREATE TABLE buoy_team_settings (
