  WHERE (json_extract(c.value,'$.field')='id' AND json_extract(c.value,'$.value')=a.id)
     OR (json_extract(c.value,'$.field')='name' AND json_extract(c.value,'$.value')=json_extract(a.document,'$.name'))
 );
