CREATE TABLE buoy_ai_requests(id TEXT PRIMARY KEY,actor_id TEXT NOT NULL,feature TEXT NOT NULL,status TEXT NOT NULL,reserved_minor INTEGER NOT NULL,charged_minor INTEGER NOT NULL DEFAULT 0,occurred_at TEXT NOT NULL);
CREATE TABLE buoy_ai_minutes(actor_id TEXT NOT NULL,minute INTEGER NOT NULL,requests INTEGER NOT NULL,PRIMARY KEY(actor_id,minute));
CREATE TABLE buoy_ai_proposals(id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES buoy_accounts(id) ON DELETE CASCADE,account_revision TEXT NOT NULL,kind TEXT NOT NULL,line TEXT NOT NULL,line_number INTEGER NOT NULL,created_by TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',task_id TEXT);

CREATE TABLE buoy_communications(id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES buoy_accounts(id) ON DELETE CASCADE,person_id TEXT REFERENCES buoy_customer_people(id) ON DELETE CASCADE,data_class TEXT NOT NULL CHECK(data_class IN ('emails','tickets')),observed_on TEXT NOT NULL,body TEXT NOT NULL);
CREATE TABLE buoy_communication_scores(account_id TEXT PRIMARY KEY REFERENCES buoy_accounts(id) ON DELETE CASCADE,document TEXT NOT NULL);
CREATE TRIGGER buoy_communication_erasure AFTER DELETE ON buoy_communications BEGIN
 DELETE FROM buoy_communication_scores WHERE account_id=OLD.account_id;
 DELETE FROM buoy_scorecard_history WHERE account_id=OLD.account_id AND json_type(document,'$.inputs.values."communications.score"') IS NOT NULL;
 DELETE FROM buoy_scorecard_results WHERE account_id=OLD.account_id AND json_type(document,'$.inputs.values."communications.score"') IS NOT NULL;
END;

-- This product marker carries no consent, provider policy or execution authority.
CREATE TABLE buoy_communication_state (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),
 configured INTEGER NOT NULL CHECK(configured IN (0,1))
);
INSERT INTO buoy_communication_state(singleton,configured)
 SELECT 1, CASE WHEN json_type(document,'$.communicationsEnabled') IS NULL THEN 0 ELSE 1 END
 FROM buoy_ai_settings WHERE singleton=1;

-- Connector notices need no account when the source has not been bound yet.
CREATE TABLE buoy_connection_notices (
 id TEXT PRIMARY KEY, connection_id TEXT NOT NULL REFERENCES buoy_connections(id),
 person_id TEXT NOT NULL, source TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL,
 created_at TEXT NOT NULL, read_at TEXT, UNIQUE(person_id,source)
);

CREATE TABLE buoy_revenue_resolutions (
 id TEXT PRIMARY KEY,
 account_id TEXT NOT NULL REFERENCES buoy_accounts(id) ON DELETE CASCADE,
 account_revision TEXT NOT NULL,
 contract_version_id TEXT NOT NULL,
 contract_revision TEXT NOT NULL,
 billing_snapshot_id TEXT NOT NULL,
 resolved_by TEXT NOT NULL,
 resolved_at TEXT NOT NULL,
 reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 1 AND 2000),
 UNIQUE(account_id,contract_version_id,contract_revision,billing_snapshot_id)
);
CREATE TRIGGER buoy_revenue_resolution_immutable BEFORE UPDATE ON buoy_revenue_resolutions BEGIN
 SELECT RAISE(ABORT,'Revenue resolutions are immutable');
END;
CREATE TRIGGER buoy_revenue_resolution_delete BEFORE DELETE ON buoy_revenue_resolutions
 WHEN EXISTS(SELECT 1 FROM buoy_accounts WHERE id=OLD.account_id) BEGIN
 SELECT RAISE(ABORT,'Revenue resolutions are immutable');
END;

-- Existing grants retain their explicit IDs. All-account authority is opt-in.
ALTER TABLE buoy_integration_tokens ADD COLUMN account_scope TEXT NOT NULL DEFAULT 'explicit' CHECK(account_scope IN ('explicit','all'));
-- Earlier issuance instants are unknown; never invent historical metadata.
ALTER TABLE buoy_integration_tokens ADD COLUMN label TEXT NOT NULL DEFAULT 'Integration credential';
ALTER TABLE buoy_integration_tokens ADD COLUMN created_at TEXT;
ALTER TABLE buoy_integration_tokens ADD COLUMN revoked_reason TEXT CHECK(revoked_reason IN ('revocation','account_erasure'));
DROP TRIGGER buoy_integration_account_removed;
CREATE TRIGGER buoy_integration_account_removed BEFORE DELETE ON buoy_accounts
BEGIN
 UPDATE buoy_integration_tokens
 SET revoked_reason=CASE WHEN revoked_at IS NULL THEN 'account_erasure' ELSE revoked_reason END,
     revoked_at=COALESCE(revoked_at,CAST(strftime('%s','now') AS INTEGER)*1000),
     account_ids=(SELECT json_group_array(value) FROM json_each(account_ids) WHERE value<>OLD.id)
 WHERE EXISTS(SELECT 1 FROM json_each(account_ids) WHERE value=OLD.id);
END;

-- Copied native person evidence follows the same erasure and hold custody.
CREATE TRIGGER buoy_trust_person_erasure BEFORE DELETE ON buoy_customer_people
BEGIN
 DELETE FROM buoy_trust_proposals WHERE OLD.id IN(json_extract(evidence,'$.evidence.claim.personId'),json_extract(evidence,'$.evidence.preview.person.id'),json_extract(evidence,'$.evidence.preview.previous.person_id'));
END;
CREATE TRIGGER buoy_trust_hold_insert BEFORE INSERT ON buoy_trust_proposals
BEGIN
 INSERT INTO buoy_privacy_hold_versions(person_id,record_kind,record_key,captured_at,document)
 SELECT h.person_id,'buoy_trust_proposals',json_array(NEW.id),strftime('%Y-%m-%dT%H:%M:%fZ','now'),json_object('id',NEW.id,'account_id',NEW.account_id,'related_account_id',NEW.related_account_id,'kind',NEW.kind,'evidence',NEW.evidence,'fingerprint',NEW.fingerprint,'status',NEW.status,'prepared_by',NEW.prepared_by,'prepared_at',NEW.prepared_at,'reviewed_by',NEW.reviewed_by,'reviewed_at',NEW.reviewed_at,'reason',NEW.reason)
 FROM buoy_privacy_holds h WHERE (h.person_id IN(json_extract(NEW.evidence,'$.evidence.claim.personId'),json_extract(NEW.evidence,'$.evidence.preview.person.id'),json_extract(NEW.evidence,'$.evidence.preview.previous.person_id')) OR EXISTS(SELECT 1 FROM buoy_customer_memberships m WHERE m.person_id=h.person_id AND m.account_id IN(NEW.account_id,NEW.related_account_id)))
 AND NOT EXISTS(SELECT 1 FROM buoy_privacy_hold_versions v WHERE v.person_id=h.person_id AND v.record_kind='buoy_trust_proposals' AND v.record_key=json_array(NEW.id) AND v.document=json_object('id',NEW.id,'account_id',NEW.account_id,'related_account_id',NEW.related_account_id,'kind',NEW.kind,'evidence',NEW.evidence,'fingerprint',NEW.fingerprint,'status',NEW.status,'prepared_by',NEW.prepared_by,'prepared_at',NEW.prepared_at,'reviewed_by',NEW.reviewed_by,'reviewed_at',NEW.reviewed_at,'reason',NEW.reason));
END;
